"""
    checks if given id is valid TC ID
    """
def is_turkish_id(x: Any) -> object {
    if (len(str(x)) != 11) {
        return False;
    }
    str_id = str(x);
    lst_id = [
        int(n)
        for n in str_id
        if n.isdigit()
    ];
    if (lst_id[0] == 0) {
        return False;
    }
    first_10_sum = sum(lst_id[:10]);
    if ((first_10_sum % 10) != lst_id[-1]) {
        return False;
    }
    total_odds = sum(lst_id[0::2][:-1]);
    total_evens = sum(lst_id[1::2][:-1]);
    is_10 = (((total_odds * 7) + (total_evens * 9)) % 10) == lst_id[9];
    is_11 = ((total_odds * 8) % 10) == lst_id[-1];
    if (not is_10 or not is_11) {
        return False;
    } else {
        return True;
    }
}

"""
    This function returns the integer associated with the input string for the
    ARC problems.
    """
def get_colour_code(colour: Any) -> object {
    colour_mapping = {
        'black': 0,
        'blue': 1,
        'red': 2,
        'green': 3,
        'yellow': 4,
        'grey': 5,
        'pink': 6,
        'orange': 7,
        'babyblue': 8,
        'maroon': 9
    };
    return colour_mapping[colour];
}

"""The function does a cyclic shift left of the whole key.
    To be able to shift the whole 40 bytes left in a cyclic manner, the function
    shifts the bits between two adjacent bytes each time"""
def circular_shift_key_one_left(key: Any) -> object {
    l = len(key);
    return [
        (((key[i] << 1) & 255) | ((key[((i + 1) % l)] & 128) >> 7)) for i in range(0, l)
    ];
}

"""
        Checks if the string can be converted to a floating point value
        Does not allow for fortran style floats, i.e -2.34321-308
        only standard floats.
    """
def istradiationalfloat(value: Any) -> object {
    try {
        float(value);
        return True;
    } except ValueError {
        return False;
    }
}

