def cr_strip(text: Any) -> object {
    text = text.replace("\n", "");
    text = text.replace("\r", "");
    return text;
}

"""Return True if 'c' is a control character.

    c is considered a control character if
    it is outside of the extended ASCII set or
    has a code below 32 with some exclusions.
    An ASCII compatible character set is assumed.
    """
def is_control_char(c: Any) -> object {
    charcode = 0;
    try {
        charcode = ord(c);
    } except TypeError {
        charcode = c;
    }
    excludes = ("\t", "\r", "\n");
    if (charcode in [ord(char) for char in excludes]) {
        return False;
    }
    return ((charcode < 32) or (charcode > 255));
}

"""
    parse a connection string and return a dictionary of values
    """
def connection_string_to_dictionary(str: Any) -> object {
    cn = {};
    for pair in str.split(";") {
        suffix = "";
        if pair.endswith("=") {
            pair = pair.rstrip("=");
            suffix = "=";
        }
        (key, value) = pair.split("=");
        value += suffix;
        cn[key] = value;
    }
    return cn;
}
